
import genesyscloudService from '@/services/genesyscloud-service'
import platformClient from 'purecloud-platform-client-v2'
import { defineComponent } from 'vue'
import QueueMemberDetails from './QueueMemberDetails.vue'
import QueueStatistics from './QueueStatistics.vue'
import UserStatusStatistics from './UserStatusStatistics.vue'

// Extend PresenceDefinition interface to allow storing original presence
declare module 'purecloud-platform-client-v2' {
  namespace Models {
    interface PresenceDefinition {
      originalSystemPresence?: string;
    }
  }
}

// Create a converter function to convert OutOfOffice to OutOfOfficeData
function convertToOutOfOfficeData(outOfOffice: platformClient.Models.OutOfOffice | undefined | null): any {
  if (!outOfOffice) return null;
  
  return {
    active: outOfOffice.active === true, // Ensure it's boolean
    indefinite: outOfOffice.indefinite === true, // Ensure it's boolean
    startDate: outOfOffice.startDate,
    endDate: outOfOffice.endDate
  };
}

export default defineComponent({
  name: 'QueueDetails',
  components: {
    QueueMemberDetails,
    QueueStatistics,
    UserStatusStatistics
  },
  props: {
    queue: {
      type: Object as () => platformClient.Models.Queue,
      required: true
    }
  },
  data () {
    return {
      queueMembers: [] as platformClient.Models.QueueMember[],
      isLoading: false,
      showNoUsers: false,
      serverTime: new Date(),
      oWaiting: 0,
      oInteracting: 0,
      mediaTypeStats: {} as { [key: string]: { waiting: number, interacting: number } },
      userPresenceMetrics: {} as { [key: string]: number },
      notRespondingCount: 0,
      activityTopic: '',
      activityTopicExpiration: null as Date | null,
      expirationTimer: null as number | null
    }
  },
  computed: {
    sortedQueueMembers(): platformClient.Models.QueueMember[] {
      return [...this.queueMembers].sort((a, b) => {
        if (a.joined === b.joined) return 0;
        return a.joined ? -1 : 1;
      });
    }
  },
  async created (): Promise<void> {
    console.log('QueueDetails created')
    await genesyscloudService.fetchPresenceDefinitions()
    this.serverTime = await genesyscloudService.fetchServerTime()
    await genesyscloudService.createNotificationChannel(this.onNotification)
    await this.loadQueueMembers()
    await this.loadInitialData()
  },
  unmounted () {
    if (this.expirationTimer) {
      clearTimeout(this.expirationTimer);
    }
  },
  watch: {
    queue: async function (): Promise<void> {
      console.log('Queue changed:', this.queue)
      this.isLoading = true
      this.showNoUsers = false

      if (!this.queue?.id) {
        console.error('Queue not found')
        return
      }

      await this.loadQueueMembers()
      await this.loadInitialData()
      this.isLoading = false
    }
  },
  methods: {
    async loadInitialData(): Promise<void> {
        await this.loadQueueObservations();
        await this.loadRoutingActivity();
    },

    async loadQueueObservations(): Promise<void> {
        if (!this.queue.id) {
            console.error('Queue ID is undefined')
            return
        }
        console.log('Loading queue observations for queue:', this.queue.id)
        const observations = await genesyscloudService.getQueueObservations(this.queue.id)
        
        const newMediaTypeStats: { [key: string]: { waiting: number, interacting: number } } = {}

        if (observations && observations.results) {
            for (const result of observations.results) {
                if (result.group.mediaType) {
                    const mediaType = result.group.mediaType
                    if (!newMediaTypeStats[mediaType]) {
                        newMediaTypeStats[mediaType] = { waiting: 0, interacting: 0 }
                    }
                    for (const stat of result.data) {
                        if (stat.metric === 'oWaiting') {
                            newMediaTypeStats[mediaType].waiting = stat.stats.count
                        } else if (stat.metric === 'oInteracting') {
                            newMediaTypeStats[mediaType].interacting = stat.stats.count
                        }
                    }
                }
            }
        }
        this.mediaTypeStats = newMediaTypeStats
        this.updateTotalStats()
        console.log('Queue statistics loaded:', this.mediaTypeStats)
    },

    async loadRoutingActivity(): Promise<void> {
        if (!this.queue.id) {
            console.error('Queue ID is undefined')
            return
        }
        const activity = await genesyscloudService.getRoutingActivity(this.queue.id);
        if (activity && activity.results) {
            const activityData = activity.results.length > 0 ? activity.results[0].data : [];
            this.processUserStatistics(activityData);

            const activityTopic = activity.subscriptions && activity.subscriptions.length > 0 ? activity.subscriptions[0].topic : undefined;
            const subscriptionExpirationDate = activity.subscriptionExpirationDate;
            this.activityTopic = activityTopic;
            if (subscriptionExpirationDate) {
                this.activityTopicExpiration = new Date(subscriptionExpirationDate);
                this.scheduleSubscriptionRefresh();
            }
            this.updateSubscriptions();
        }
    },

    processUserStatistics(data: any[]): void {
        const newUserPresenceMetrics: { [key: string]: number } = {};
        let notRespondingCount = 0;

        for (const stat of data) {
            console.log(`Processing metric: ${stat.metric}, qualifier: ${stat.qualifier}, count: ${stat.count}`);
            if (stat.metric === 'oUserPresences') {
                let presenceName = stat.qualifier;
                if (stat.secondaryQualifier) { 
                    presenceName = stat.secondaryQualifier;
                }
                newUserPresenceMetrics[presenceName] = stat.count;
            } else if (stat.metric === 'oUserRoutingStatuses' && stat.qualifier === 'NOT_RESPONDING') {
                notRespondingCount = stat.count;
            }
        }
        this.userPresenceMetrics = newUserPresenceMetrics;
        this.notRespondingCount = notRespondingCount;
    },

    scheduleSubscriptionRefresh(): void {
      if (this.expirationTimer) {
        clearTimeout(this.expirationTimer);
      }
      if (this.activityTopicExpiration) {
        const now = new Date();
        const refreshTime = this.activityTopicExpiration.getTime() - now.getTime() - 60000; // 1 minute before expiration
        if (refreshTime > 0) {
          this.expirationTimer = setTimeout(() => {
            this.loadRoutingActivity();
          }, refreshTime);
        }
      }
    },
    updateTotalStats (): void {
      this.oWaiting = 0
      this.oInteracting = 0
      for (const mediaType in this.mediaTypeStats) {
        this.oWaiting += this.mediaTypeStats[mediaType].waiting
        this.oInteracting += this.mediaTypeStats[mediaType].interacting
      }
    },
    async loadQueueMembers (): Promise<void> {
      if (!this.queue.id) {
        console.error('Queue ID is undefined')
        return
      }
      console.log('Loading queue members for queue:', this.queue.id)
      this.queueMembers = await genesyscloudService.getMembersOfQueue(this.queue.id) ?? []
      console.log('Queue members loaded:', this.queueMembers)

      // Apply effective status that considers out of office
      this.updateEffectiveStatuses()

      // modifiedDate can be > now (!) -> modifiedDate := now
      const adjustedNow = new Date(Date.now() + genesyscloudService.getServerOffset())
      this.queueMembers.forEach(member => {
        if (member.user?.presence?.modifiedDate) {
          const modifiedDate = new Date(member.user.presence.modifiedDate)
          if (modifiedDate > adjustedNow) {
            member.user.presence.modifiedDate = adjustedNow.toISOString()
          }
        }
      })

      if (this.queueMembers.length <= 0) {
        console.log('No users in queue')
        this.showNoUsers = true
      }
      await this.updateSubscriptions()
    },

    async updateSubscriptions (): Promise<void> {
      if (!this.queue.id) return
      const userIds = this.queueMembers.map(member => member.id ?? '')
      const topics = userIds.map(userId => ({ id: `v2.users.${userId}?presence&routingStatus&outofoffice` }))
      topics.push({ id: `v2.routing.queues.${this.queue.id}.users` })
      topics.push({ id: `v2.analytics.queues.${this.queue.id}.observations` })
      if (this.activityTopic) {
        topics.push({ id: this.activityTopic });
      }
      await genesyscloudService.subscribeToTopics(topics)
    },

    // Update all members' effective statuses
    updateEffectiveStatuses(): void {
      this.queueMembers.forEach(member => {
        if (member.user?.presence?.presenceDefinition) {
          const presenceId = member.user.presence.presenceDefinition.id || ''
          
          // Convert OutOfOffice to OutOfOfficeData
          const outOfOfficeData = convertToOutOfOfficeData(member.user.outOfOffice)
          
          // Set the effective status that considers out of office state
          const effectiveStatus = genesyscloudService.getEffectiveStatus(presenceId, outOfOfficeData)
          
          // Store the original system presence
          const originalPresence = member.user.presence.presenceDefinition.systemPresence || ''
          
          // Store original presence as a custom property
          member.user.presence.presenceDefinition.originalSystemPresence = originalPresence
          
          // Override system presence with effective status
          member.user.presence.presenceDefinition.systemPresence = effectiveStatus
        }
      })
    },
    // Callback function when Genesys Cloud fires notifications based on the queue members
    onNotification (data: any): void {
      const topicName = data.topicName
      const eventBody = data.eventBody

      if (topicName === this.activityTopic) {
        this.processUserStatistics(eventBody.data);
        return;
      }

      if (topicName.startsWith('v2.analytics.queues.')) {
        const mediaType = eventBody.group.mediaType
        if (mediaType && this.mediaTypeStats[mediaType]) {
          for (const metric of eventBody.data[0].metrics) {
            if (metric.metric === 'oWaiting') {
              this.mediaTypeStats[mediaType].waiting = metric.stats.count
            } else if (metric.metric === 'oInteracting') {
              this.mediaTypeStats[mediaType].interacting = metric.stats.count
            }
          }
          this.updateTotalStats()
        } else if (!mediaType) {
            const newUserPresenceMetrics: { [key: string]: number } = {};
            for (const metric of eventBody.data[0].metrics) {
                if (metric.metric === 'oUserPresences' && metric.qualifier) {
                    const presenceId = metric.qualifier;
                    const presenceName = genesyscloudService.getPresenceName(presenceId);
                    newUserPresenceMetrics[presenceName] = metric.stats.count;
                } else if (metric.metric === 'oOnQueueUsers') {
                    newUserPresenceMetrics['On Queue'] = metric.stats.count;
                }
            }
            this.userPresenceMetrics = newUserPresenceMetrics;
        }
      } else if (topicName.includes('v2.users')) {
        const topicRegex = /(v2\.users\.)(.*)\.(.*)/g
        const match = topicRegex.exec(topicName)
        if (!match) return

        const userId = match[2]
        const updatedProperty = match[3]
        console.log('User event:', userId, updatedProperty)

        const queueMember = this.queueMembers.find(member => member.id === userId)
        if (!queueMember?.user) {
          console.error('User not found in queue')
          return
        }

        switch (updatedProperty) {
          case 'presence': {
            if (queueMember.user.presence && eventBody.presenceDefinition) {
              // Store the original presence ID and system presence before updating
              const presenceId = eventBody.presenceDefinition.id || ''
              const originalSystemPresence = genesyscloudService.getSystemPresence(presenceId)

              // Update the presence definition
              queueMember.user.presence.presenceDefinition = eventBody.presenceDefinition

              // Always store the original system presence
              if (queueMember.user.presence.presenceDefinition) {
                queueMember.user.presence.presenceDefinition.originalSystemPresence = originalSystemPresence
              }

              // Safely update modifiedDate
              // modifiedDate can be > now (!) -> modifiedDate := now
              const modifiedDate = new Date(eventBody.modifiedDate)
              const adjustedNow = new Date(Date.now() + genesyscloudService.getServerOffset())
              if (modifiedDate > adjustedNow) {
                queueMember.user.presence.modifiedDate = adjustedNow.toISOString()
              } else {
                queueMember.user.presence.modifiedDate = eventBody.modifiedDate
              }

              // After updating presence, recalculate the effective status
              this.updateEffectiveStatusForMember(queueMember)
            }
            break
          }
          case 'routingStatus': {
            // Update routing status
            queueMember.user.routingStatus = eventBody.routingStatus
            break
          }
          case 'outofoffice': {
            // Update out of office data
            queueMember.user.outOfOffice = eventBody

            // After updating outOfOffice, recalculate the effective status
            this.updateEffectiveStatusForMember(queueMember)
            break
          }
        }
      } else if (topicName.includes('v2.routing.queues')) {
        const metadata = data.metadata
        if (eventBody.queueId === this.queue.id) {
          switch (metadata.action) {
            case 'add': {
              genesyscloudService.getUserDetails(eventBody.user.id).then(user => {
                this.queueMembers.push({ id: user.id, name: user.name, user: user, joined: eventBody.joined })
                this.updateSubscriptions()
              })
              break
            }
            case 'delete': {
              const index = this.queueMembers.findIndex(member => member.id === eventBody.user.id)
              if (index !== -1) {
                this.queueMembers.splice(index, 1)
                this.updateSubscriptions()
              }
              break
            }
            case 'update': {
              const queueMember = this.queueMembers.find(member => member.id === eventBody.user.id)
              if (queueMember) {
                queueMember.joined = eventBody.joined
              }
              break
            }
          }
        }
      }
    },
    updateEffectiveStatusForMember(queueMember: platformClient.Models.QueueMember): void {
      if (!queueMember?.user?.presence?.presenceDefinition?.id) return;
      
      const presenceId = queueMember.user.presence.presenceDefinition.id;
      
      // Store the original system presence for later color determination
      // This ensures we remember the base status even when overridden by Out of Office
      if (queueMember.user.presence.presenceDefinition && !queueMember.user.presence.presenceDefinition.originalSystemPresence) {
        queueMember.user.presence.presenceDefinition.originalSystemPresence = 
          genesyscloudService.getPresenceName(presenceId);
      }
      
      // Convert to OutOfOfficeData
      const outOfOfficeData = convertToOutOfOfficeData(queueMember.user.outOfOffice);
      
      // Update the effective status considering the current presence and out of office state
      const effectiveStatus = genesyscloudService.getEffectiveStatus(presenceId, outOfOfficeData);
      
      // Update the displayed status - with proper type safety
      if (queueMember.user.presence.presenceDefinition) {
        queueMember.user.presence.presenceDefinition.systemPresence = effectiveStatus;
      }
    }
  }
})
